@router.post("/reports/{report_id}/generate-pdf")
def trigger_pdf_generation(
    report_id: int,
    background_tasks: BackgroundTasks,
    user: User = Depends(get_current_user),
    db: Session = Depends(get_db)
):
    report = db.query(Report).filter(Report.id == report_id, Report.owner_id == user.id).first()
    if not report:
        raise HTTPException(status_code=404, detail="Report not found")

    background_tasks.add_task(render_and_email_report, report_id, user.email)
    return {"status": "enqueued", "report_id": report_id, "recipient": user.email}
